import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"PUNTO DI ACCUMULAZIONE","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/cb/cbb.md","filePath":"lezioni/c_analisi/cb/cbb.md"}`),a={name:`lezioni/c_analisi/cb/cbb.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="punto-di-accumulazione" tabindex="-1">PUNTO DI ACCUMULAZIONE <a class="header-anchor" href="#punto-di-accumulazione" aria-label="Permalink to “PUNTO DI ACCUMULAZIONE”">​</a></h1><p>Un punto si dice di accumulazione per un insieme di punti se qualunque suo intorno contiene sempre almeno un punto dell&#39;insieme diverso dal nostro punto.</p><p>Almeno uno vuol dire che, visto che posso prendere infiniti intervalli sempre più piccoli, di punti ne conterrà infiniti.</p><p>Ad esempio considero l&#39;insieme formato dai punti <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mn>2</mn></mrow><annotation encoding="application/x-tex">1/2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/2</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mn>4</mn></mrow><annotation encoding="application/x-tex">1/4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/4</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mn>8</mn></mrow><annotation encoding="application/x-tex">1/8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/8</span></span></span></span>, ... Se provate a procedere vedete che questi punti tendono a <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>, allora si dice che <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> è un punto di accumulazione per questo insieme: infatti per quanto io possa prendere piccolo un intervallo che contenga <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> ci sarà sempre un punto della successione diverso da <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> contenuto nell&#39;intervallo (anzi ce ne saranno infiniti).</p><p>A questo proposito possiamo enunciare un piccolo teorema:</p><blockquote><p class="text-purple">[Se un insieme infinito di punti è limitato allora ammette sempre un punto di accumulazione]</p><p>Infatti se l&#39;insieme è limitato vuol dire che si trova in un intervallo limitato e se è infinito io posso dividere l&#39;intervallo a metà e almeno in una metà ci devono essere infiniti punti; posso ancora dividere ancora quella metà a metà e in una parte ci saranno sempre infiniti punti e così via di seguito, quindi poiché in un mezzo intervallino ci saranno sempre infiniti punti allora in quell&#39;intervallino dovrà esserci un punto di accumulazione.</p></blockquote><p>In questa figura il punto di accumulazione è quello a destra.</p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};